import React from 'react';

export interface Quote {
  text: string;
  source: string;
  author: string;
}

export interface Level {
  name: string;
  tier: string; // The major rank group (e.g. 'Egg', 'Tadpole')
  minXP: number;
  color: string;
  shade: string;
  requiredWpm: number;
}

export interface GameState {
  xp: number;
  completedQuotes: number;
}

export interface TestResult {
  id: number;
  date: string;
  wpm: number;
  xpEarned: number;
  mode: GameMode;
  quoteText: string;      
  mistakes: string[];     
  retryCount: number;     
}

export type MusicSource = 'NONE' | 'YOUTUBE' | 'SPOTIFY' | 'GENERATED' | 'SUNO';

export interface MusicConfig {
  source: MusicSource;
  presetId: string;
}

export type MechanicalSoundPreset = 'THOCK' | 'CLICKY' | 'BUBBLE' | 'TYPEWRITER';

export type ReadAheadLevel = 'NONE' | 'FOCUS' | 'ULTRA' | 'BLIND';

export type TTSMode = 'OFF' | 'QUOTE' | 'WORD' | 'FLOW' | 'NEXT' | 'SCOUT';

export interface Settings {
  ghostEnabled: boolean;
  readAheadLevel: ReadAheadLevel; 
  sfxEnabled: boolean;
  mechanicalSoundEnabled: boolean; 
  mechanicalSoundPreset: MechanicalSoundPreset; 
  ambientVolume: number; 
  musicConfig: MusicConfig;
  themeId: string; 
  autoStartMusic: boolean; 
  ttsMode: TTSMode; 
}

export type GameMode = 'QUOTES' | 'HARDCORE' | 'XWORDS' | 'XQUOTES' | 'PRACTICE' | 'MINIGAMES' | 'BLITZ' | 'DRILL';

export enum GameStatus {
  IDLE = 'IDLE',
  PLAYING = 'PLAYING',
  COMPLETED = 'COMPLETED', 
  FAILED = 'FAILED', 
  DRILLING = 'DRILLING'
}

export interface Theme {
  id: string;
  name: string;
  description: string;
  minTier: string; 
  colors: {
    frog: Record<number, string>; 
    stone: Record<number, string>; 
    background: string;
  };
}

export interface AchievementStats {
  wpm: number;
  totalQuotes: number;
  maxStreak: number; 
  currentStreak: number;
  dailyStreak: number;
  mode: GameMode;
  totalTime: number; 
  arcadeScore?: number;
  arcadeWave?: number;
}

export interface Achievement {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  category: 'SPEED' | 'STREAK' | 'VOLUME' | 'MASTERY' | 'HIDDEN' | 'PRACTICE' | 'TIME' | 'CONSISTENCY' | 'ARCADE';
  condition: (stats: AchievementStats) => boolean;
}

export interface NotificationItem {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  type: 'ACHIEVEMENT' | 'UNLOCK' | 'INFO';
}

export interface PracticeWord {
  word: string;
  proficiency: number; // 0 to 3 (3 = Mastered)
  lastPracticed: number;
}

export interface WeakWord {
  word: string;
  mistakeCount: number;
  lastMistake: number;
}

export interface WordPerformance {
  word: string;
  wpm: number;
  isCorrect: boolean;
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { soundEngine } from '../utils/soundEngine';
import { Timer, Zap, RotateCcw, X, LogOut, ArrowRight, Sparkles, Brain, Target, ShieldAlert, CheckCircle2 } from 'lucide-react';
import { fetchBlitzWords } from '../services/quoteService';
import { PracticeWord, WordPerformance } from '../types';

interface BlitzGameProps {
  smartQueue: PracticeWord[];
  onGameOver: (wpm: number, xp: number, mistakes: string[]) => void;
  onWordPerformance: (perf: WordPerformance) => void;
  onExit: () => void;
}

const BlitzGame: React.FC<BlitzGameProps> = ({ smartQueue, onGameOver, onWordPerformance, onExit }) => {
  const [gameState, setGameState] = useState<'START' | 'PLAYING' | 'GAMEOVER' | 'DRILL_PENALTY'>('START');
  const [timeLeft, setTimeLeft] = useState(60);
  const [words, setWords] = useState<string[]>([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [input, setInput] = useState('');
  const [isError, setIsError] = useState(false);
  const [correctCount, setCorrectCount] = useState(0);
  const [mistakeWords, setMistakeWords] = useState<string[]>([]);

  // Drill State
  const [drillTarget, setDrillTarget] = useState<string | null>(null);
  const [drillCount, setDrillCount] = useState(0);
  const DRILL_REQUIRED = 17;

  const wordStartTimeRef = useRef<number>(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const timerRef = useRef<number | undefined>(undefined);

  const initGame = useCallback(() => {
    const wordList = fetchBlitzWords(150, smartQueue);
    setWords(wordList);
    setCurrentIdx(0);
    setInput('');
    setIsError(false);
    setTimeLeft(60);
    setCorrectCount(0);
    setMistakeWords([]);
    setDrillTarget(null);
    setDrillCount(0);
    setGameState('PLAYING');
    wordStartTimeRef.current = performance.now();
    setTimeout(() => inputRef.current?.focus(), 50);
  }, [smartQueue]);

  useEffect(() => {
    if (gameState === 'PLAYING') {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            endGame();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => clearInterval(timerRef.current);
  }, [gameState]);

  const endGame = () => {
    setGameState('GAMEOVER');
    clearInterval(timerRef.current);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (gameState === 'DRILL_PENALTY') {
        handleDrillInput(e.target.value);
        return;
    }

    if (gameState !== 'PLAYING') return;
    const val = e.target.value;
    const targetWord = words[currentIdx];

    // Check for space (Next Word)
    if (val.endsWith(' ')) {
        const typed = val.trim();
        if (typed === targetWord) {
            const now = performance.now();
            const duration = (now - wordStartTimeRef.current) / 1000;
            const wordWpm = Math.round((targetWord.length / 5) / (duration / 60));
            onWordPerformance({ word: targetWord, wpm: wordWpm, isCorrect: true });
            setCorrectCount(prev => prev + 1);
            setCurrentIdx(prev => prev + 1);
            setInput('');
            setIsError(false);
            soundEngine.playKeypress();
            wordStartTimeRef.current = now;
            if (currentIdx > words.length - 20) {
                setWords(prev => [...prev, ...fetchBlitzWords(50, smartQueue)]);
            }
        } else {
            triggerFail(targetWord);
        }
        return;
    }

    // Incremental Accuracy Check
    if (!targetWord.startsWith(val)) {
        triggerFail(targetWord);
    } else {
        setIsError(false);
        setInput(val);
        soundEngine.playKeypress();
    }
  };

  const triggerFail = (word: string) => {
    soundEngine.playError();
    onWordPerformance({ word, wpm: 0, isCorrect: false });
    setMistakeWords(prev => [...prev, word]);
    setDrillTarget(word);
    setDrillCount(0);
    setGameState('DRILL_PENALTY');
    setInput('');
    clearInterval(timerRef.current);
  };

  const handleDrillInput = (val: string) => {
    if (!drillTarget) return;

    if (val.endsWith(' ')) {
        const typed = val.trim();
        if (typed === drillTarget) {
            soundEngine.playKeypress();
            const nextCount = drillCount + 1;
            setDrillCount(nextCount);
            setInput('');
            if (nextCount >= DRILL_REQUIRED) {
                soundEngine.playSuccess();
                setGameState('GAMEOVER'); // After drill, Blitz run is over
            }
        } else {
            soundEngine.playError();
            setDrillCount(0);
            setInput('');
        }
        return;
    }

    if (!drillTarget.startsWith(val)) {
        soundEngine.playError();
        setDrillCount(0);
        setInput('');
    } else {
        setInput(val);
        soundEngine.playKeypress();
    }
  };

  const totalChars = words.slice(0, currentIdx).reduce((acc, w) => acc + w.length + 1, 0);
  const realWpm = Math.round((totalChars / 5));

  if (gameState === 'START') {
      return (
          <div className="w-full max-w-4xl mx-auto h-[450px] bg-white rounded-3xl border-4 border-frog-green/20 flex flex-col items-center justify-center shadow-xl p-8">
              <div className="text-center space-y-6">
                  <div className="w-20 h-20 bg-frog-100 rounded-full flex items-center justify-center mx-auto mb-4 border-2 border-frog-400 shadow-lg">
                      <Zap className="w-10 h-10 text-frog-600" />
                  </div>
                  <h2 className="text-4xl font-black text-stone-800 tracking-tight">BLITZ 200</h2>
                  <p className="text-stone-500 text-lg max-w-md mx-auto">Master the 200 most common English words. 60 seconds on the clock. **One mistake fails and forces a 17x repetition drill.**</p>

                  <div className="flex gap-4 justify-center">
                      <button onClick={onExit} className="px-6 py-3 text-stone-400 font-bold hover:text-stone-600">Back</button>
                      <button onClick={initGame} className="px-10 py-4 bg-frog-green hover:bg-green-500 text-white font-black text-xl rounded-full shadow-lg shadow-frog-100 transition-transform hover:scale-105">START BLITZ</button>
                  </div>
              </div>
          </div>
      );
  }

  if (gameState === 'DRILL_PENALTY') {
      return (
          <div className="w-full max-w-4xl mx-auto h-[450px] bg-red-50 rounded-[3rem] border-4 border-red-200 flex flex-col items-center justify-center shadow-2xl p-10 animate-in fade-in zoom-in-95 duration-500">
              <div className="flex items-center gap-3 mb-8">
                  <Brain className="w-8 h-8 text-red-500 animate-pulse" />
                  <h3 className="text-3xl font-black text-red-700 tracking-tight uppercase">Cognitive Reinforcement</h3>
              </div>

              <p className="text-red-500 font-bold text-sm mb-12 flex items-center gap-2">
                  <ShieldAlert className="w-4 h-4" /> Repeat the failed word <span className="underline font-black">{DRILL_REQUIRED} times</span> perfectly to clear.
              </p>

              <div className="relative group mb-8">
                  <div className="text-7xl font-black text-red-200/50 tracking-widest select-none text-center">
                      {drillTarget}
                  </div>
                  <div className="absolute inset-0 flex items-center justify-center text-7xl font-black tracking-widest text-red-600">
                      {input}
                  </div>
              </div>

              <div className="w-full max-w-md h-4 bg-red-100 rounded-full overflow-hidden border border-red-200 mb-4">
                  <div 
                    className="h-full bg-red-500 transition-all duration-300 shadow-[0_0_10px_rgba(239,68,68,0.5)]"
                    style={{ width: `${(drillCount / DRILL_REQUIRED) * 100}%` }}
                  ></div>
              </div>
              <div className="text-red-600 font-black text-2xl font-mono">
                  {drillCount} <span className="text-sm opacity-50">/</span> {DRILL_REQUIRED}
              </div>

              <input 
                ref={inputRef}
                value={input}
                onChange={handleInputChange}
                className="opacity-0 absolute inset-0 cursor-default"
                autoFocus
              />
          </div>
      );
  }

  if (gameState === 'GAMEOVER') {
      return (
          <div className="w-full max-w-4xl mx-auto h-[450px] bg-stone-900 rounded-3xl flex flex-col items-center justify-center text-white p-8 shadow-2xl">
              <div className="text-center space-y-4 animate-in zoom-in-95">
                  <div className="text-frog-green font-black text-7xl">{realWpm}</div>
                  <div className="text-stone-400 uppercase tracking-widest font-bold text-sm">Words Per Minute</div>

                  <div className="grid grid-cols-2 gap-8 mt-4">
                      <div className="text-center">
                          <div className="text-xs text-stone-500 uppercase font-bold">Status</div>
                          <div className="text-xl font-mono text-frog-green flex items-center gap-1"><CheckCircle2 className="w-4 h-4" /> Learned</div>
                      </div>
                      <div className="text-center">
                          <div className="text-xs text-stone-500 uppercase font-bold">Total Words</div>
                          <div className="text-xl font-mono">{correctCount}</div>
                      </div>
                  </div>

                  <div className="flex gap-4 justify-center mt-12">
                      <button onClick={onExit} className="px-6 py-3 bg-stone-800 hover:bg-stone-700 rounded-xl font-bold flex items-center gap-2"><LogOut className="w-4 h-4" /> Exit</button>
                      <button onClick={initGame} className="px-6 py-3 bg-frog-green hover:bg-green-500 text-white rounded-xl font-bold flex items-center gap-2"><RotateCcw className="w-4 h-4" /> New Run</button>
                  </div>
              </div>
          </div>
      );
  }

  return (
    <div className="w-full max-w-4xl mx-auto h-[450px] bg-white rounded-[3rem] border border-stone-200 shadow-xl flex flex-col relative overflow-hidden">
        <div className="flex justify-between items-center p-8 border-b border-stone-100">
            <div className="flex items-center gap-6">
                <div className="flex flex-col">
                    <div className="text-3xl font-black text-frog-green leading-none">{realWpm}</div>
                    <div className="text-[9px] font-bold text-stone-400 uppercase tracking-widest mt-1">EST. WPM</div>
                </div>
                <div className="h-10 w-px bg-stone-100"></div>
                <div className="flex flex-col">
                    <div className="text-3xl font-black text-stone-800 leading-none">{correctCount}</div>
                    <div className="text-[9px] font-bold text-stone-400 uppercase tracking-widest mt-1">WORDS</div>
                </div>
            </div>

            <div className="bg-stone-50 px-6 py-3 rounded-2xl flex items-center gap-3 border border-stone-100">
                <Timer className={`w-5 h-5 ${timeLeft < 10 ? 'text-red-500' : 'text-stone-400'}`} />
                <span className={`text-4xl font-black font-mono leading-none ${timeLeft < 10 ? 'text-red-500 animate-pulse' : 'text-stone-700'}`}>{timeLeft}</span>
            </div>

            <button onClick={onExit} className="p-2 hover:bg-stone-100 rounded-full text-stone-300 transition-colors"><X className="w-6 h-6" /></button>
        </div>

        <div className="flex-1 p-10 flex flex-col items-center justify-center relative">
            <div className="w-full flex flex-wrap gap-x-6 gap-y-4 justify-center items-center text-3xl font-mono font-medium max-h-[160px] overflow-hidden opacity-90">
                {words.slice(currentIdx, currentIdx + 12).map((w, i) => {
                    const isActive = i === 0;
                    return (
                        <span key={i} className={`relative px-2 transition-all duration-200 ${isActive ? 'text-stone-900 font-black scale-110' : 'text-stone-200'}`}>
                            {isActive && (
                                <div className="absolute -bottom-2 left-0 right-0 h-1 bg-frog-green rounded-full shadow-[0_0_10px_rgba(64,214,114,0.5)]"></div>
                            )}
                            {w}
                        </span>
                    );
                })}
            </div>

            <div className="mt-12 relative w-full max-w-sm">
                <input 
                    ref={inputRef}
                    value={input}
                    onChange={handleInputChange}
                    className={`w-full text-center text-4xl font-mono font-bold bg-stone-50 border-2 rounded-2xl py-4 focus:outline-none transition-all ${isError ? 'border-red-500 bg-red-50' : 'border-stone-100 focus:border-frog-green focus:bg-white'}`}
                    placeholder="Type words..."
                    autoFocus
                />
            </div>
        </div>

        <div className="h-2 bg-stone-100 w-full">
            <div className={`h-full transition-all duration-1000 ease-linear ${timeLeft < 10 ? 'bg-red-500' : 'bg-frog-green'}`} style={{ width: `${(timeLeft / 60) * 100}%` }}></div>
        </div>
    </div>
  );
};

export default BlitzGame;

import React, { useState, useEffect } from 'react';
import { X, TrendingUp, History, Calendar, ArrowLeft, BookOpen, Eraser, RotateCcw, Clock, Flag, User, Flame, Edit2, Library, Zap, Target, Star, AlertCircle, ChevronRight, BarChart3, LayoutGrid, Trophy, Brain, Activity } from 'lucide-react';
import { TestResult, WeakWord } from '../types';
import { getCurrentLevel } from '../utils/gameLogic';

interface StatsModalProps {
  isOpen: boolean;
  onClose: () => void;
  avgWpm: number;
  history: TestResult[];
  onPractice: (mistakes: string[]) => void;
  totalTime: number; 
  joinDate: string;
  streak: number; 
  userName: string;
  setUserName: (name: string) => void;
  completedTestsCount: number;
  userXP: number;
}

const StatsModal: React.FC<StatsModalProps> = ({ 
  isOpen, onClose, avgWpm, history, onPractice,
  totalTime, joinDate, streak, userName, setUserName, completedTestsCount, userXP
}) => {
  const [activeTab, setActiveTab] = useState<'OVERVIEW' | 'HISTORY' | 'WEAK_WORDS'>('OVERVIEW');
  const [selectedResult, setSelectedResult] = useState<TestResult | null>(null);
  const [isEditingName, setIsEditingName] = useState(false);
  const [editNameValue, setEditNameValue] = useState(userName);
  const [weakWords, setWeakWords] = useState<WeakWord[]>([]);

  useEffect(() => {
    setEditNameValue(userName);
    // Load weak words from local storage
    const stored = localStorage.getItem('frogType_weakWords');
    if (stored) {
        setWeakWords(JSON.parse(stored));
    }
  }, [userName, isOpen]);

  if (!isOpen) return null;

  const formatDate = (isoString: string) => {
    const date = new Date(isoString);
    return new Intl.DateTimeFormat('en-US', {
      month: 'short', day: 'numeric', year: 'numeric'
    }).format(date);
  };

  const formatDateTime = (isoString: string) => {
    const date = new Date(isoString);
    return new Intl.DateTimeFormat('en-US', {
      month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit'
    }).format(date);
  };

  const formatDuration = (seconds: number) => {
     const h = Math.floor(seconds / 3600);
     const m = Math.floor((seconds % 3600) / 60);
     if (h > 0) return `${h}h ${m}m`;
     return `${m}m`;
  };

  const handleNameSave = () => {
      const trimmed = editNameValue.trim();
      if (trimmed) setUserName(trimmed);
      else setEditNameValue(userName);
      setIsEditingName(false);
  };

  const currentLevel = getCurrentLevel(userXP);
  const bestWpm = history.length > 0 ? Math.max(...history.map(h => h.wpm)) : 0;
  const totalMistakes = history.reduce((acc, curr) => acc + (curr.mistakes?.length || 0), 0);

  if (selectedResult) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-stone-900/40 backdrop-blur-sm animate-in fade-in duration-200" onClick={onClose}>
        <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[85vh]" onClick={(e) => e.stopPropagation()}>
             <div className="flex justify-between items-center p-5 border-b border-stone-100 bg-white sticky top-0 z-10">
                <div className="flex items-center gap-2">
                   <button onClick={() => setSelectedResult(null)} className="p-1 hover:bg-stone-100 rounded-full transition-colors mr-1">
                     <ArrowLeft className="w-5 h-5 text-stone-500" />
                   </button>
                   <div>
                       <h2 className="text-lg font-black text-stone-800 tracking-tight">Run Details</h2>
                       <p className="text-xs text-stone-400 font-medium">{formatDateTime(selectedResult.date)}</p>
                   </div>
                </div>
                <button onClick={onClose} className="p-2 -mr-2 text-stone-400 hover:text-stone-600 rounded-full hover:bg-stone-50 transition-colors"><X className="w-5 h-5" /></button>
             </div>
             <div className="overflow-y-auto p-6 space-y-6 custom-scrollbar bg-stone-50/50">
                <div className="bg-white p-4 rounded-xl border border-stone-200 shadow-sm">
                   <div className="flex items-center gap-2 text-xs font-bold text-stone-400 uppercase tracking-wider mb-2"><BookOpen className="w-3 h-3" /> Quote Text</div>
                   <p className="font-mono text-lg leading-relaxed text-stone-700">{selectedResult.quoteText || "Details unavailable."}</p>
                </div>
                <div className="grid grid-cols-3 gap-3">
                   <div className="bg-white p-3 rounded-xl border border-stone-200 shadow-sm text-center">
                       <div className="text-[10px] font-bold text-stone-400 uppercase">Speed</div>
                       <div className="text-xl font-black text-frog-green">{selectedResult.wpm} WPM</div>
                   </div>
                   <div className="bg-white p-3 rounded-xl border border-stone-200 shadow-sm text-center">
                       <div className="text-[10px] font-bold text-stone-400 uppercase">Retries</div>
                       <div className="text-xl font-black text-stone-700">{selectedResult.retryCount || 0}</div>
                   </div>
                   <div className="bg-white p-3 rounded-xl border border-stone-200 shadow-sm text-center">
                       <div className="text-[10px] font-bold text-stone-400 uppercase">XP</div>
                       <div className="text-xl font-black text-stone-700">+{selectedResult.xpEarned}</div>
                   </div>
                </div>
                <div className="bg-white p-4 rounded-xl border border-stone-200 shadow-sm">
                   <div className="flex items-center justify-between mb-3">
                       <div className="flex items-center gap-2 text-xs font-bold text-stone-400 uppercase tracking-wider"><Eraser className="w-3 h-3" /> Mistakes ({selectedResult.mistakes?.length || 0})</div>
                       {(selectedResult.mistakes?.length || 0) > 0 && (
                           <button onClick={() => { onPractice(selectedResult.mistakes); onClose(); }} className="text-[10px] font-bold text-white bg-red-500 hover:bg-red-600 px-3 py-1 rounded-full flex items-center gap-1 shadow-sm transition-transform active:scale-95"><RotateCcw className="w-3 h-3" /> Practice These</button>
                       )}
                   </div>
                   {(selectedResult.mistakes?.length || 0) > 0 ? (
                       <div className="flex flex-wrap gap-2">
                          {selectedResult.mistakes?.map((word, i) => (
                              <span key={i} className="px-2 py-1 bg-red-50 text-red-600 text-xs font-bold rounded border border-red-100">{word}</span>
                          ))}
                       </div>
                   ) : (
                       <p className="text-xs text-stone-400 italic">Perfect run! No mistakes to practice.</p>
                   )}
                </div>
             </div>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-stone-900/40 backdrop-blur-sm animate-in fade-in duration-200" onClick={onClose}>
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[85vh] h-[600px]" onClick={(e) => e.stopPropagation()}>
        <div className="bg-white border-b border-stone-100 sticky top-0 z-20">
            <div className="flex justify-between items-start p-6 pb-2">
                <div className="flex items-center gap-4">
                    <div className="w-16 h-16 bg-frog-green/10 rounded-full flex items-center justify-center text-4xl shadow-inner ring-4 ring-white">🐸</div>
                    <div>
                        <div className="flex items-center gap-2">
                            {isEditingName ? (
                                <div className="flex items-center gap-1">
                                    <input autoFocus className="font-black text-2xl text-stone-800 bg-stone-50 border-b-2 border-frog-green outline-none w-40" value={editNameValue} onChange={(e) => setEditNameValue(e.target.value)} onBlur={handleNameSave} onKeyDown={(e) => e.key === 'Enter' && handleNameSave()} />
                                    <button onClick={handleNameSave} className="text-frog-green text-xs font-bold uppercase hover:bg-frog-green/10 p-1 rounded">Save</button>
                                </div>
                            ) : (
                                <h2 className="font-black text-2xl text-stone-800 tracking-tight flex items-center gap-2 group cursor-pointer hover:text-frog-green transition-colors" onClick={() => setIsEditingName(true)}>{userName} <Edit2 className="w-4 h-4 text-stone-300 opacity-0 group-hover:opacity-100 transition-opacity" /></h2>
                            )}
                        </div>
                        <div className="flex flex-col gap-0.5 mt-1">
                            <p className="text-xs text-stone-400 font-medium flex items-center gap-1"><User className="w-3 h-3" /> {currentLevel.tier} Rank</p>
                            <p className="text-xs text-stone-400 font-medium flex items-center gap-1"><Calendar className="w-3 h-3" /> Joined {formatDate(joinDate)}</p>
                        </div>
                    </div>
