// Helper to sanitize text for standard keyboards
const normalizeText = (text: string): string => {
  return text
    .replace(/[\u2013\u2014]/g, "-")      // Replace em-dash and en-dash with standard hyphen
    .replace(/[\u2018\u2019]/g, "'")      // Replace smart single quotes with straight single quote
    .replace(/[\u201C\u201D]/g, '"')      // Replace smart double quotes with straight double quote
    .replace(/…/g, "...")                 // Replace ellipsis character with three dots
    .trim();
};

// Precise 1-20 Level Mapping
const LEVEL_ORDER = [
  'Egg III', 'Egg II', 'Egg I',
  'Tadpole III', 'Tadpole II', 'Tadpole I',
  'Polliwog III', 'Polliwog II', 'Polliwog I',
  'Froglet III', 'Froglet II', 'Froglet I',
  'Hopper III', 'Hopper II', 'Hopper I',
  'Tree Frog III', 'Tree Frog II', 'Tree Frog I',
  'Bullfrog', 'Frog Sage'
];

// Enhanced difficulty scoring
const getQuoteDifficulty = (text: string): number => {
  const normalized = normalizeText(text);
  const words = normalized.split(/\s+/);

  const lengthScore = normalized.length;
  const avgWordLength = words.length > 0 ? lengthScore / words.length : 0;
  const complexityScore = avgWordLength * 8; 
  const punctuationCount = (normalized.match(/[.,;?!'"\-:()]/g) || []).length;
  const technicalScore = punctuationCount * 3;

  return lengthScore + complexityScore + technicalScore;
};

// PERFORMANCE OPTIMIZATION: Pre-calculate and sort once
const SORTED_QUOTES = [...QUOTES].map(q => ({
    ...q,
    difficulty: getQuoteDifficulty(q.quoteText),
    normalizedText: normalizeText(q.quoteText)
})).sort((a, b) => a.difficulty - b.difficulty);

export const PRACTICE_ORDER = "enitrlsauoychgmpbkvwjqxz".split('');

const getDifficultyConfig = (tier: string) => {
    switch(tier) {
        case 'Egg': return { minLen: 2, maxLen: 4, punctProb: 0, count: 8 };
        case 'Tadpole': return { minLen: 3, maxLen: 6, punctProb: 0, count: 10 };
        case 'Polliwog': return { minLen: 4, maxLen: 8, punctProb: 0.1, count: 12 };
        case 'Froglet': return { minLen: 4, maxLen: 10, punctProb: 0.3, count: 15 };
        case 'Hopper': return { minLen: 5, maxLen: 12, punctProb: 0.5, count: 15 };
        case 'Tree Frog': return { minLen: 5, maxLen: 15, punctProb: 0.7, count: 18 };
        case 'Bullfrog': return { minLen: 6, maxLen: 20, punctProb: 0.9, count: 20 };
        case 'Frog Sage': return { minLen: 6, maxLen: 99, punctProb: 1.0, count: 25 };
        default: return { minLen: 2, maxLen: 5, punctProb: 0, count: 10 };
    }
};

const applyPunctuation = (word: string, prob: number) => {
    if (Math.random() > prob) return word;

    const r = Math.random();
    if (r < 0.4) return word + ',';
    if (r < 0.7) return word + '.';
    if (r < 0.8) return word + '?';
    if (r < 0.9) return word + '!';
    if (r < 0.95) return `"${word}"`;
    return word + ';';
};

export const fetchTenFastWords = (count: number = 100, smartQueue: PracticeWord[] = []): string[] => {
    // Top 200 words from COMMON_WORDS
    const top200 = COMMON_WORDS.slice(0, 200);

    // Pick words from smartQueue that are unmastered
    const masteryWords = smartQueue
        .filter(pw => pw.proficiency < 3)
        .sort((a,b) => a.lastPracticed - b.lastPracticed)
        .map(pw => pw.word);

    const words: string[] = [];
    for (let i = 0; i < count; i++) {
        // 25% chance to inject a word from the mastery queue if available
        if (masteryWords.length > 0 && Math.random() < 0.25) {
            const pick = masteryWords[Math.floor(Math.random() * Math.min(masteryWords.length, 10))];
            words.push(pick);
        } else {
            words.push(top200[Math.floor(Math.random() * top200.length)]);
        }
    }
    return words;
};

export const fetchQuotes = async (
    count: number = 3, 
    exclude: string[] = [], 
    levelName: string = 'Egg III', 
    mode: string = 'QUOTES', 
    practiceLevel: number = 0,
    charStats: Record<string, number> = {},
    smartPracticeQueue: PracticeWord[] = []
): Promise<Quote[]> => {

  if (mode === 'PRACTICE') {
      const tier = levelName.split(' ')[0] || 'Egg';
      const config = getDifficultyConfig(tier);

      let availableWords = COMMON_WORDS.filter(w => w.length >= config.minLen && w.length <= config.maxLen);
      if (availableWords.length < 50) availableWords = COMMON_WORDS.filter(w => w.length <= config.maxLen);

      const masteryWords = smartPracticeQueue
          .filter(pw => pw.proficiency < 3)
          .sort((a,b) => a.lastPracticed - b.lastPracticed);

      const quotes: Quote[] = [];
      for(let i=0; i<count; i++) {
         const sentenceWords: string[] = [];

         // Increase mastery injection to 40% for better repetition
         const masteryCount = Math.min(masteryWords.length, Math.ceil(config.count * 0.4));
         const commonCount = config.count - masteryCount;

         if (masteryCount > 0) {
             const candidates = masteryWords.slice(0, 15).sort(() => 0.5 - Math.random());
             for(let k=0; k<masteryCount; k++) {
                 if (candidates[k]) sentenceWords.push(candidates[k].word);
             }
         }

         for(let j=0; j<commonCount; j++) {
             let word = availableWords[Math.floor(Math.random() * availableWords.length)];
             word = applyPunctuation(word, config.punctProb);
             sentenceWords.push(word);
         }

         const shuffledSentence = sentenceWords.sort(() => 0.5 - Math.random()).join(" ");
         quotes.push({
             text: shuffledSentence,
             source: "Mastery Loop",
             author: `Level: ${tier} | Reviewing: ${masteryCount} words`
         });
      }
      return quotes;
  }

  // --- STANDARD QUOTES ---
  const bucketCount = 20;
  const bucketSize = Math.ceil(SORTED_QUOTES.length / bucketCount);
  let difficultyIndex = LEVEL_ORDER.indexOf(levelName);
  if (difficultyIndex === -1) difficultyIndex = 0;
  if (mode === 'HARDCORE') difficultyIndex = 19; 

  const startIndex = difficultyIndex * bucketSize;
  const endIndex = Math.min(startIndex + bucketSize, SORTED_QUOTES.length);
  let tierQuotes = SORTED_QUOTES.slice(startIndex, endIndex);
  if (tierQuotes.length < 3 && difficultyIndex > 0) {
      tierQuotes = SORTED_QUOTES.slice(Math.max(0, startIndex - bucketSize), endIndex);
  }
  if (tierQuotes.length === 0) tierQuotes = SORTED_QUOTES.slice(0, 20);

  const excludeSet = new Set(exclude.map(normalizeText)); 
  let available = tierQuotes.filter(q => !excludeSet.has(q.normalizedText));
  if (available.length === 0) available = tierQuotes;

  const shuffled = [...available].sort(() => 0.5 - Math.random());
  const selected = shuffled.slice(0, count);

  return selected.map(q => ({
    text: q.normalizedText,
    source: "Wisdom",
    author: q.quoteAuthor || "Unknown"
  }));
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { soundEngine } from '../utils/soundEngine';
import { Timer, Zap, RotateCcw, X, LogOut, ArrowRight, Sparkles, Brain, Target, ShieldAlert, CheckCircle2 } from 'lucide-react';
import { fetchTenFastWords } from '../services/quoteService';
import { PracticeWord, WordPerformance } from '../types';

interface TenFastGameProps {
  smartQueue: PracticeWord[];
  onGameOver: (wpm: number, xp: number, mistakes: string[]) => void;
  onWordPerformance: (perf: WordPerformance) => void;
  onExit: () => void;
}

const TenFastGame: React.FC<TenFastGameProps> = ({ smartQueue, onGameOver, onWordPerformance, onExit }) => {
  const [gameState, setGameState] = useState<'START' | 'PLAYING' | 'GAMEOVER' | 'DRILL_PENALTY'>('START');
  const [timeLeft, setTimeLeft] = useState(60);
  const [words, setWords] = useState<string[]>([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [input, setInput] = useState('');
  const [isError, setIsError] = useState(false);
  const [correctCount, setCorrectCount] = useState(0);
  const [mistakeWords, setMistakeWords] = useState<string[]>([]);

  // Drill State
  const [drillTarget, setDrillTarget] = useState<string | null>(null);
  const [drillCount, setDrillCount] = useState(0);
  const DRILL_REQUIRED = 17;

  const wordStartTimeRef = useRef<number>(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const timerRef = useRef<number | undefined>(undefined);

  const initGame = useCallback(() => {
    const wordList = fetchTenFastWords(150, smartQueue);
    setWords(wordList);
    setCurrentIdx(0);
    setInput('');
    setIsError(false);
    setTimeLeft(60);
    setCorrectCount(0);
    setMistakeWords([]);
    setDrillTarget(null);
    setDrillCount(0);
    setGameState('PLAYING');
    wordStartTimeRef.current = performance.now();
    setTimeout(() => inputRef.current?.focus(), 50);
  }, [smartQueue]);

  useEffect(() => {
    if (gameState === 'PLAYING') {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            handleFinalize();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => clearInterval(timerRef.current);
  }, [gameState]);

  const handleFinalize = () => {
    setGameState('GAMEOVER');
    clearInterval(timerRef.current);

    // Calculate final stats for history
    const totalChars = words.slice(0, currentIdx).reduce((acc, w) => acc + w.length + 1, 0);
    const finalWpm = Math.round((totalChars / 5));
    const xp = Math.max(5, Math.floor(finalWpm * (correctCount / 10)));
    onGameOver(finalWpm, xp, mistakeWords);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (gameState === 'DRILL_PENALTY') {
        handleDrillInput(e.target.value);
        return;
    }

    if (gameState !== 'PLAYING') return;
    const val = e.target.value;
    const targetWord = words[currentIdx];

    // Check for space (Next Word)
    if (val.endsWith(' ')) {
        const typed = val.trim();
        if (typed === targetWord) {
            const now = performance.now();
            const duration = (now - wordStartTimeRef.current) / 1000;
            const wordWpm = Math.round((targetWord.length / 5) / (duration / 60));
            onWordPerformance({ word: targetWord, wpm: wordWpm, isCorrect: true });
            setCorrectCount(prev => prev + 1);
            setCurrentIdx(prev => prev + 1);
            setInput('');
            setIsError(false);
            soundEngine.playKeypress();
            wordStartTimeRef.current = now;
            if (currentIdx > words.length - 20) {
                setWords(prev => [...prev, ...fetchTenFastWords(50, smartQueue)]);
            }
        } else {
            triggerFail(targetWord);
        }
        return;
    }

    // Incremental Accuracy Check
    if (!targetWord.startsWith(val)) {
        triggerFail(targetWord);
    } else {
        setIsError(false);
        setInput(val);
        soundEngine.playKeypress();
    }
  };

  const triggerFail = (word: string) => {
    soundEngine.playError();
    onWordPerformance({ word, wpm: 0, isCorrect: false });
    setMistakeWords(prev => [...prev, word]);
    setDrillTarget(word);
    setDrillCount(0);
    setGameState('DRILL_PENALTY');
    setInput('');
    clearInterval(timerRef.current);
  };

  const handleDrillInput = (val: string) => {
    if (!drillTarget) return;

    if (val.endsWith(' ')) {
        const typed = val.trim();
        if (typed === drillTarget) {
            soundEngine.playKeypress();
            const nextCount = drillCount + 1;
            setDrillCount(nextCount);
            setInput('');
            if (nextCount >= DRILL_REQUIRED) {
                soundEngine.playSuccess();
                handleFinalize();
            }
        } else {
            soundEngine.playError();
            setDrillCount(0);
            setInput('');
        }
        return;
    }

    if (!drillTarget.startsWith(val)) {
        soundEngine.playError();
        setDrillCount(0);
        setInput('');
    } else {
        setInput(val);
        soundEngine.playKeypress();
    }
  };

  const totalChars = words.slice(0, currentIdx).reduce((acc, w) => acc + w.length + 1, 0);
  const realWpm = Math.round((totalChars / 5));

  if (gameState === 'START') {
      return (
          <div className="w-full max-w-4xl mx-auto h-[450px] bg-white rounded-3xl border-4 border-frog-green/20 flex flex-col items-center justify-center shadow-xl p-8">
              <div className="text-center space-y-6">
                  <div className="w-20 h-20 bg-frog-100 rounded-full flex items-center justify-center mx-auto mb-4 border-2 border-frog-400 shadow-lg">
                      <Zap className="w-10 h-10 text-frog-600" />
                  </div>
                  <h2 className="text-4xl font-black text-stone-800 tracking-tight">10 FAST</h2>
                  <p className="text-stone-500 text-lg max-w-md mx-auto">Master the most common English words. 60 seconds on the clock. **One mistake fails and forces a 17x repetition drill.**</p>

                  <div className="flex gap-4 justify-center">
                      <button onClick={onExit} className="px-6 py-3 text-stone-400 font-bold hover:text-stone-600">Back</button>
                      <button onClick={initGame} className="px-10 py-4 bg-frog-green hover:bg-green-500 text-white font-black text-xl rounded-full shadow-lg shadow-frog-100 transition-transform hover:scale-105">START RUN</button>
                  </div>
              </div>
          </div>
      );
  }

  if (gameState === 'DRILL_PENALTY') {
      return (
          <div className="w-full max-w-4xl mx-auto h-[450px] bg-red-50 rounded-[3rem] border-4 border-red-200 flex flex-col items-center justify-center shadow-2xl p-10 animate-in fade-in zoom-in-95 duration-500">
              <div className="flex items-center gap-3 mb-8">
                  <Brain className="w-8 h-8 text-red-500 animate-pulse" />
                  <h3 className="text-3xl font-black text-red-700 tracking-tight uppercase">Cognitive Reinforcement</h3>
              </div>

              <p className="text-red-500 font-bold text-sm mb-12 flex items-center gap-2">
                  <ShieldAlert className="w-4 h-4" /> Repeat the failed word <span className="underline font-black">{DRILL_REQUIRED} times</span> perfectly to clear.
              </p>

              <div className="relative group mb-8">
                  <div className="text-7xl font-black text-red-200/50 tracking-widest select-none text-center">
